const pubsub = new PubSub();

// ================================
// EVENTS
// ================================
const EVENTS = {
  TRACK_ADDED: 'TRACK_ADDED',
  ALBUM_ADDED: 'ALBUM_ADDED',
  ARTIST_UPDATED: 'ARTIST_UPDATED',
  PLAYLIST_UPDATED: 'PLAYLIST_UPDATED',
  TRACK_RANK_UPDATED: 'TRACK_RANK_UPDATED',
};

// ================================
// HELPERS
// ================================
const getPagination = (page = 1, limit = 10) => {
  const skip = (page - 1) * limit;
  return { skip, limit: Math.min(limit, 100) };
};

const getPageInfo = (total, page, limit) => {
  const totalPages = Math.ceil(total / limit);
  return {
    hasNextPage: page < totalPages,
    hasPreviousPage: page > 1,
    currentPage: page,
    totalPages,
  };
};

// ================================
// AUTH (SANS JWT)
// ================================
const getUser = async (context) => {
  const userId = context.req?.headers?.['x-user-id'];

  if (!userId) {
    throw new Error('Non authentifié (x-user-id manquant)');
  }

  const user = await User.findById(userId);
  if (!user) {
    throw new Error('Utilisateur introuvable');
  }

  return user;
};

const requireAdmin = async (context) => {
  const user = await getUser(context);
  if (user.role !== 'admin') {
    throw new Error('Accès réservé aux administrateurs');
  }
  return user;
};

// ================================
// RESOLVERS
// ================================
const resolvers = {

  // ================================
  // TYPES
  // ================================
  LikedTrack: {
    id: (parent) => parent._id.toString(),
    user: async (parent) => User.findById(parent.user).exec(),
    track: async (parent) => {
      if (parent.track && parent.track._id) return parent.track;
      return Track.findById(parent.track).exec();
    },
  },

  Artist: {
    id: (parent) => parent._id.toString(),
    albums: async (parent) => Album.find({ artist: parent._id }).exec(),
  },

  Album: {
    id: (parent) => parent._id.toString(),
    artist: async (parent) => Artist.findById(parent.artist).exec(),
    tracks: async (parent) =>
      Track.find({ album: parent._id }).sort({ position: 1 }).exec(),
  },

  Track: {
    id: (parent) => parent._id.toString(),
    album: async (parent) => Album.findById(parent.album).exec(),
    artist: async (parent) => Artist.findById(parent.artist).exec(),
  },

  Playlist: {
    id: (parent) => parent._id.toString(),
    tracks: async (parent) =>
      Track.find({ _id: { $in: parent.tracks } }).exec(),
  },

  User: {
    id: (parent) => parent._id.toString(),
  },

  // ================================
  // QUERIES
  // ================================
  Query: {

    artists: async (_, { filter = {}, sort, page = 1, limit = 10 }) => {
      const query = {};
      if (filter.searchName) query.name = new RegExp(filter.searchName, 'i');

      const { skip } = getPagination(page, limit);

      const [nodes, totalCount] = await Promise.all([
        Artist.find(query).skip(skip).limit(limit).exec(),
        Artist.countDocuments(query).exec(),
      ]);

      return { nodes, totalCount, pageInfo: getPageInfo(totalCount, page, limit) };
    },

    artist: (_, { id }) => Artist.findById(id).exec(),

    albums: async (_, args) => Album.find().exec(),
    album: (_, { id }) => Album.findById(id).exec(),

    tracks: async (_, args) => Track.find().limit(args.limit || 20).exec(),
    track: (_, { id }) => Track.findById(id).exec(),

    playlists: async (_, { isPublic }) => {
      const query = {};
      if (isPublic !== undefined) query.public = isPublic;
      return Playlist.find(query).exec();
    },

    playlist: (_, { id }) => Playlist.findById(id).exec(),

    genres: () => Genre.find().exec(),
    genre: (_, { id }) => Genre.findById(id).exec(),

    // ✅ remplacé JWT ici
    likedTracks: async (_, __, context) => {
      const user = await getUser(context);

      return LikedTrack.find({ user: user._id })
        .populate('track')
        .exec();
    },

    me: async (_, __, context) => {
      return getUser(context);
    },

    users: async (_, __, context) => {
      await requireAdmin(context);
      return User.find().exec();
    },
  },

  // ================================
  // MUTATIONS
  // ================================
  Mutation: {

    // AUTH SIMPLE (sans JWT)
    register: async (_, { input }) => {
      const existing = await User.findOne({ email: input.email });
      if (existing) throw new Error('Email déjà utilisé');

      const hashed = await bcrypt.hash(input.password, 12);

      const user = await User.create({
        ...input,
        password: hashed,
        role: 'user',
      });

      return {
        token: user._id.toString(), // ⚠️ simple token = userId
        user,
      };
    },

    login: async (_, { input }) => {
      const user = await User.findOne({ email: input.email });
      if (!user) throw new Error('Identifiants invalides');

      const ok = await bcrypt.compare(input.password, user.password);
      if (!ok) throw new Error('Identifiants invalides');

      return {
        token: user._id.toString(), // ⚠️ pas JWT
        user,
      };
    },

    // ARTISTS
    createArtist: async (_, { input }, context) => {
      await requireAdmin(context);
      const artist = await Artist.create(input);
      pubsub.publish(EVENTS.ARTIST_UPDATED, { artistUpdated: artist });
      return artist;
    },

    updateArtist: async (_, { id, input }, context) => {
      await requireAdmin(context);
      return Artist.findByIdAndUpdate(id, input, { new: true });
    },

    deleteArtist: async (_, { id }, context) => {
      await requireAdmin(context);
      return Artist.findByIdAndDelete(id);
    },

    // ALBUMS
    createAlbum: async (_, { input }, context) => {
      await requireAdmin(context);

      const { artistId, ...rest } = input;
      const album = await Album.create({ ...rest, artist: artistId });

      pubsub.publish(EVENTS.ALBUM_ADDED, { albumAdded: album });
      return album;
    },

    // TRACKS
    createTrack: async (_, { input }, context) => {
      await requireAdmin(context);

      const { albumId, artistId, ...rest } = input;

      const track = await Track.create({
        ...rest,
        album: albumId,
        artist: artistId,
      });

      pubsub.publish(EVENTS.TRACK_ADDED, { trackAdded: track });
      return track;
    },

    // LIKE SYSTEM (sans JWT)
    likeTrack: async (_, { trackId }, context) => {
      const user = await getUser(context);

      const exists = await LikedTrack.findOne({
        user: user._id,
        track: trackId,
      });

      if (exists) throw new Error('Déjà liké');

      return LikedTrack.create({
        user: user._id,
        track: trackId,
      });
    },

    unlikeTrack: async (_, { trackId }, context) => {
      const user = await getUser(context);

      const deleted = await LikedTrack.findOneAndDelete({
        user: user._id,
        track: trackId,
      });

      if (!deleted) throw new Error('Like introuvable');

      return { success: true };
    },

    // PLAYLISTS
    createPlaylist: async (_, { input }, context) => {
      const user = await getUser(context);

      return Playlist.create({
        ...input,
        userId: user._id,
      });
    },

    addTrackToPlaylist: async (_, { playlistId, trackId }, context) => {
      const user = await getUser(context);

      const playlist = await Playlist.findById(playlistId);
      if (!playlist) throw new Error('Playlist introuvable');

      if (playlist.userId?.toString() !== user._id.toString()) {
        throw new Error('Accès refusé');
      }

      if (!playlist.tracks.includes(trackId)) {
        playlist.tracks.push(trackId);
        await playlist.save();
      }

      return playlist;
    },
  },

  // ================================
  // SUBSCRIPTIONS
  // ================================
  Subscription: {
    trackAdded: {
      subscribe: () =>
        pubsub.asyncIterableIterator([EVENTS.TRACK_ADDED]),
    },

    albumAdded: {
      subscribe: withFilter(
        () => pubsub.asyncIterableIterator([EVENTS.ALBUM_ADDED]),
        (payload, variables) => {
          if (!variables.artistId) return true;
          return payload.albumAdded.artist.toString() === variables.artistId;
        }
      ),
    },
  },
};

module.exports = resolvers;
